<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {Plus,Trash2,Upload,ShieldCheck} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {useVintro} from '../composables/useVintro';const router=useRouter();const {addService}=useVintro();const saving=ref(false);const workshop=ref(true);const parts=ref(['Engine oil','Oil filter']);const form=ref({type:'Oil service',date:'2026-08-26',mileage:87420,workshop:'Garage Jerala',cost:240,currency:'CHF',notes:''});const save=()=>{saving.value=true;setTimeout(()=>{addService({id:crypto.randomUUID(),date:new Date(form.value.date).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}),dateISO:form.value.date,mileage:Number(form.value.mileage),type:form.value.type,category:'Service',workshop:workshop.value?form.value.workshop:'Owner recorded',parts:parts.value.filter(Boolean),notes:form.value.notes,cost:Number(form.value.cost),currency:form.value.currency as 'CHF'|'EUR',verified:false});router.push('/vehicle/bmw-320d/history')},650)}
</script>
<template><PageHeader title="Add service" back="/vehicle/bmw-320d/history"/><form class="container-app max-w-3xl py-7" @submit.prevent="save"><div><p class="eyebrow">New maintenance record</p><h1 class="page-title mt-2">What was done?</h1><p class="mt-3 text-muted">Add the details you have. You can update the record later.</p></div><div class="mt-8 space-y-7"><section class="card p-5 md:p-6"><h2 class="section-title mb-5">Service details</h2><div class="grid gap-5 sm:grid-cols-2"><label><span class="label">Service type</span><select v-model="form.type" class="field"><option v-for="x in ['Oil service','Regular service','Brakes','Tires','Inspection','Repair','Other']">{{x}}</option></select></label><label><span class="label">Date</span><input v-model="form.date" type="date" required class="field nums"/></label><label><span class="label">Mileage</span><div class="relative"><input v-model="form.mileage" type="number" required class="field nums pr-12"/><span class="absolute right-4 top-3 text-sm text-muted">km</span></div></label><label><span class="label">Cost</span><div class="flex"><select v-model="form.currency" class="field w-24 rounded-r-none"><option>CHF</option><option>EUR</option></select><input v-model="form.cost" type="number" class="field rounded-l-none border-l-0 nums"/></div></label></div><label class="mt-5 flex items-center justify-between gap-4 rounded-xl bg-stone-50 p-4"><span><span class="block text-sm font-medium">Service performed by a workshop</span><span class="mt-1 block text-xs text-muted">Include the workshop in this record.</span></span><button type="button" role="switch" :aria-checked="workshop" @click="workshop=!workshop" class="relative h-7 w-12 rounded-full" :class="workshop?'bg-accent':'bg-stone-300'"><span class="absolute top-1 h-5 w-5 rounded-full bg-white transition" :class="workshop?'left-6':'left-1'"/></button></label><label v-if="workshop" class="mt-5 block"><span class="label">Workshop name</span><input v-model="form.workshop" class="field" required/></label></section><section class="card p-5 md:p-6"><div class="flex items-center justify-between"><h2 class="section-title">Parts replaced</h2><button type="button" @click="parts.push('')" class="flex items-center gap-1 text-sm font-semibold text-accent"><Plus :size="16"/>Add part</button></div><div class="mt-5 space-y-3"><div v-for="(_,i) in parts" class="flex gap-2"><input v-model="parts[i]" class="field" placeholder="Part or fluid"/><button type="button" @click="parts.splice(i,1)" class="grid w-11 shrink-0 place-items-center rounded-xl text-muted hover:bg-stone-100" aria-label="Remove part"><Trash2 :size="18"/></button></div></div></section><section class="card p-5 md:p-6"><label><span class="label">Notes</span><textarea v-model="form.notes" class="field min-h-28 resize-none" placeholder="Optional notes about the work…"/></label><button type="button" class="mt-5 flex w-full items-center justify-center gap-2 rounded-xl border border-dashed py-5 text-sm font-medium text-muted hover:bg-stone-50"><Upload :size="19"/>Upload invoice or receipt</button><div class="mt-5 flex gap-3 rounded-xl bg-emerald-50 p-4 text-sm"><ShieldCheck class="shrink-0 text-success" :size="20"/><p><strong class="block text-success">Verified record</strong><span class="text-muted">In future, participating workshops can verify this service.</span></p></div></section><button class="btn-primary w-full" :disabled="saving"><span v-if="saving" class="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white"/>{{saving?'Saving record…':'Save service'}}</button></div></form></template>
